  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Anna CuaDriverile macOS-i juurdepääsetavuse ja ekraani salvestamise õigused ning luba tal taaskäivituda. Töölaua juurdepääsu test näitab rakendusi neid muutmata. Taustateenuse juhtelemendid mõjutavad aktiivseid arvutikasutuse seansse.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Salvesta arvutikasutuse lüliti, et kasutada automaatset dovo_cua MCP-d uutel kirjutusõigusega käivitustel. MCP-d pole vaja käsitsi registreerida. Paigalda valikuline ametlik oskuste pakett; paigaldamisel lingitakse leitud agendid selles arvutis.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Valikuline, krüptitud ja ainult metaandmeid sisaldav ajalugu. Lubamine võib taustateenuse taaskäivitada. Keelamine säilitab salvestatud andmed; peatamine katkestab salvestamise ajutiselt. Toetamata järgud annavad veateate. Andmed jäävad käituskeskkonna hosti; valik „Kuva hiljutine ajalugu“ toob siia kuni 20 sündmust.',
  'Delete recorded Computer History?': 'Kas kustutada salvestatud arvutiajalugu?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Kustutab kogu salvestatud ajaloo ja selle krüptimisvõtme sellest arvutist. Seda ei saa tagasi võtta.',
