  'Start your computer': 'Käivita arvuti',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Ava arvutis Dovo ja hoia arvuti ärkvel. Ava Settings → Devices & runtime, logi sisse ja luba Dovo Connect. Logi telefonis sisse sama kontoga ja vali Connect. Internetiühenduseks pole sidumiskoodi, VPN-i ega kohalikku IP-aadressi vaja.',
  'Direct internet connection': 'Otsene internetiühendus',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN ühendab telefoni otse arvutiga. Sisu on täielikult krüptitud. Dovo Connecti lubamisel saab võrgu otseühenduse tõrke korral kasutada krüptitud releed. Relee edastab krüptitud liiklust ega saa sisu lugeda.',
  'LAN / VPN connections': 'LAN-i/VPN-i ühendused',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    "Seo LAN/VPN eraldi, et eelistada võimaluse korral seda ühendust. Kopeeri arvutis kuvatud täielik Wi-Fi, Tailscale'i, NetBird'i või HTTPS-i aadress koos pordiga. localhost ja 0.0.0.0 pole aadressid, millega telefon ühenduda saaks.",
  'Check your network': 'Kontrolli võrku',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    "Kasuta sama Wi-Fi võrku või ühenda mõlemad seadmed VPN-iga. Wi-Fi ühenduste puhul luba iPhone'i seadetes Dovol juurdepääs kohalikule võrgule.",
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Sidumiskoodid aeguvad kahe minuti pärast. CLI-koodid kinnitatakse automaatselt; töölauarakendusest saadud kood võib vajada seal kinnitamist.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Sidumine on salvestatud. Enne uue koodi loomist proovi uuesti ühenduda. Kui aadress muutus, vali selle arvuti seadetes käsk „Värskenda ühenduse aadressi”.',
