  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Agent, selle käsud ja terminalid töötavad konteineris. Ühendatakse ainult see töökoopia ja agendi sisselogimisandmed.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Peatab uue töö, mis käib ilma teie sõnumita, kui selle hinnanguline kulu jõuab piiranguni. See hõlmab robotite jätkusamme, roboti rutiinisamme, ajastatud sõnumeid ja alamagente. Iga lõim või robot loetakse koos oma alamagentidega. Robotita rutiin alustab igal käivitusel uut loendust. Määrake selle enda piirangud jaotises Seire ja piirangud. Teie järgmine sõnum või Jätka lähtestab loenduse. Ka hinnata käigud peatavad töö. Käimasolev käik lõpeb alati.',
